def find_peak_element(nums: list[int]) -> int:
    """
    Finds the index of a peak element in the array.
    A peak element is greater than its neighbors. For corner elements, it is compared to only one neighbor.
    """
    left, right = 0, len(nums) - 1

    while left < right:
        mid = (left + right) // 2

        if nums[mid] < nums[mid + 1]:
            left = mid + 1
        else:
            right = mid

    return left

