def next_permutation(s: str) -> str:
    """
    Returns the next lexicographical permutation of the input string.
    If no such permutation exists, returns the smallest permutation (sorted in ascending order).
    """
    s = list(s)
    n = len(s)

    # Step 1: Find the largest index k such that s[k] < s[k + 1]. If no such index exists, the permutation is the last permutation.
    k = -1
    for i in range(n - 1):
        if s[i] < s[i + 1]:
            k = i

    if k == -1:
        # The string is in descending order
        s.sort()
        return ''.join(s)

    # Step 2: Find the largest index l greater than k such that s[k] < s[l].
    l = -1
    for i in range(n):
        if s[k] < s[i]:
            l = i

    # Step 3: Swap the value of s[k] with that of s[l].
    s[k], s[l] = s[l], s[k]

    # Step 4: Reverse the sequence from s[k + 1] up to and including the final element s[n - 1].
    s = s[:k + 1] + s[k + 1:][::-1]

    return ''.join(s)

