def isBalanced(s: str) -> bool:
    """
    Determines if the brackets in the input string are balanced.

    Args:
    s (str): The input string containing the brackets.

    Returns:
    bool: True if the brackets are balanced, False otherwise.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if stack == [] or bracket_map[char] != stack.pop():
                return False
        else:
            continue  # ignore non-bracket characters

    return stack == []

