def check_balanced_unary(s: str) -> bool:
    """
    Checks if the given string with parentheses and unary operators is balanced.
    Ignores spaces in the string.
    """
    # Ignore spaces in the string
    s = s.replace(" ", "")
    stack = []

    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack or stack[-1] != '(':
                return False
            stack.pop()

    return len(stack) == 0

